"""Build mixins/itemphysic/physics.rs: the engine (src/lib.rs) as `pub mod engine`, then the glue
(native/physics_glue.rs). tools/hnmod.py only bundles runtime.rs, so run this after editing either file."""
import pathlib

root = pathlib.Path(__file__).resolve().parent.parent
engine = (root / "src" / "lib.rs").read_text(encoding="utf-8")
glue = (root / "native" / "physics_glue.rs").read_text(encoding="utf-8")
out = (
    "// Generated by tools/bundle_physics.py from src/lib.rs and native/physics_glue.rs: do not edit.\n"
    "#[allow(dead_code, non_upper_case_globals, clippy::all)]\npub mod engine {\n"
    + engine
    + "\n}\n\n"
    + glue
)
(root / "mixins" / "itemphysic" / "physics.rs").write_text(out, encoding="utf-8")
print("physics.rs", len(out), "bytes")
